#!/usr/bin/env node
/**
 * Generates `services/pdf/generated/pdfjsSource.ts`, a TypeScript module that
 * exports the minified pdf.js library and worker as strings.
 *
 * The PDF reader runs pdf.js inside a WebView. Inlining the library (instead of
 * loading it from a CDN) keeps the reader 100% offline and avoids sending any
 * request to external servers while the user reads.
 *
 * Runs automatically on `npm install` (postinstall). The output is git-ignored.
 */
const fs = require('fs');
const path = require('path');

const root = path.resolve(__dirname, '..');
const outDir = path.join(root, 'services', 'pdf', 'generated');
const outFile = path.join(outDir, 'pdfjsSource.ts');

function resolvePdfjsFile(file) {
  const candidates = [
    path.join(root, 'node_modules', 'pdfjs-dist', 'legacy', 'build', file),
    path.join(root, 'node_modules', 'pdfjs-dist', 'build', file),
  ];
  const found = candidates.find((candidate) => fs.existsSync(candidate));
  if (!found) {
    throw new Error(`pdfjs-dist file not found: ${file}. Run "npm install" first.`);
  }
  return found;
}

/** Serialises a script as a JS string literal that is safe to inline in <script>. */
function toSafeLiteral(source) {
  const lineSeparator = new RegExp(String.fromCharCode(0x2028), 'g');
  const paragraphSeparator = new RegExp(String.fromCharCode(0x2029), 'g');
  return JSON.stringify(source)
    .replace(/<\/script/gi, '<\\/script')
    .replace(lineSeparator, '\\u2028')
    .replace(paragraphSeparator, '\\u2029');
}

function main() {
  const lib = fs.readFileSync(resolvePdfjsFile('pdf.min.js'), 'utf8');
  const worker = fs.readFileSync(resolvePdfjsFile('pdf.worker.min.js'), 'utf8');
  const version = require(path.join(root, 'node_modules', 'pdfjs-dist', 'package.json')).version;

  fs.mkdirSync(outDir, { recursive: true });
  const content = [
    '/* eslint-disable */',
    '// AUTO-GENERATED by scripts/generate-pdfjs-bundle.js — do not edit.',
    `export const PDFJS_VERSION = ${JSON.stringify(version)};`,
    `export const PDFJS_SOURCE: string = ${toSafeLiteral(lib)};`,
    `export const PDFJS_WORKER_SOURCE: string = ${toSafeLiteral(worker)};`,
    '',
  ].join('\n');
  fs.writeFileSync(outFile, content);
  console.log(`[pdfjs] generated ${path.relative(root, outFile)} (pdf.js ${version})`);
}

try {
  main();
} catch (error) {
  console.error(`[pdfjs] ${error.message}`);
  process.exitCode = 1;
}
